  // Technique detail info
  'techniques.box.detail': '\u041A\u043E\u0440\u0438\u0441\u0442\u0435 \u0433\u0430 Navy SEALs \u0437\u0430 \u0443\u043F\u0440\u0430\u0432\u0459\u0430\u045A\u0435 \u0441\u0442\u0440\u0435\u0441\u043E\u043C. \u0408\u0435\u0434\u043D\u0430\u043A\u0435 \u0444\u0430\u0437\u0435 \u0443\u0434\u0438\u0441\u0430\u0458\u0430, \u0437\u0430\u0434\u0440\u0436\u0430\u0432\u0430\u045A\u0430, \u0438\u0437\u0434\u0438\u0441\u0430\u0458\u0430 \u0438 \u0437\u0430\u0434\u0440\u0436\u0430\u0432\u0430\u045A\u0430 \u0441\u0442\u0432\u0430\u0440\u0430\u0458\u0443 \u0443\u043C\u0438\u0440\u0443\u0458\u0443\u045B\u0438 \u0440\u0438\u0442\u0430\u043C \u043A\u043E\u0458\u0438 \u0441\u043C\u0430\u045A\u0443\u0458\u0435 \u043A\u043E\u0440\u0442\u0438\u0437\u043E\u043B \u0438 \u043F\u043E\u0431\u043E\u0459\u0448\u0430\u0432\u0430 \u0444\u043E\u043A\u0443\u0441.',
  'techniques.fourSevenEight.detail': '\u0420\u0430\u0437\u0432\u0438\u043E \u0414\u0440. \u0415\u043D\u0434\u0440\u0443 \u0412\u0430\u0458\u043B. \u041F\u0440\u043E\u0434\u0443\u0436\u0435\u043D\u0438 \u0438\u0437\u0434\u0438\u0441\u0430\u0458 \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u0430 \u043F\u0430\u0440\u0430\u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u043A\u0438 \u043D\u0435\u0440\u0432\u043D\u0438 \u0441\u0438\u0441\u0442\u0435\u043C, \u0448\u0442\u043E \u0433\u0430 \u0447\u0438\u043D\u0438 \u0438\u0434\u0435\u0430\u043B\u043D\u0438\u043C \u0437\u0430 \u0431\u0440\u0437\u043E \u0437\u0430\u0441\u043F\u0438\u0432\u0430\u045A\u0435.',
  'techniques.physioSigh.detail': '\u041E\u0442\u043A\u0440\u0438\u043E \u0421\u0442\u0435\u043D\u0444\u043E\u0440\u0434\u043E\u0432 \u043D\u0435\u0443\u0440\u043E\u043D\u0430\u0443\u0447\u043D\u0438\u043A \u0414\u0440. \u0415\u043D\u0434\u0440\u0443 \u0425\u0443\u0431\u0435\u0440\u043C\u0430\u043D. \u0414\u0432\u043E\u0441\u0442\u0440\u0443\u043A\u0438 \u0443\u0434\u0438\u0441\u0430\u0458 \u043F\u0440\u0430\u045B\u0435\u043D \u0434\u0443\u0433\u0438\u043C \u0438\u0437\u0434\u0438\u0441\u0430\u0458\u0435\u043C \u0458\u0435 \u043D\u0430\u0458\u0431\u0440\u0436\u0438 \u043D\u0430\u0447\u0438\u043D \u0437\u0430 \u0441\u043C\u0430\u045A\u0435\u045A\u0435 \u0441\u0442\u0440\u0435\u0441\u0430 \u0443 \u0440\u0435\u0430\u043B\u043D\u043E\u043C \u0432\u0440\u0435\u043C\u0435\u043D\u0443.',
  'techniques.coherence.detail': '\u0414\u0438\u0441\u0430\u045A\u0435 \u043E\u0434 5,5 \u0443\u0434\u0438\u0441\u0430\u0458\u0430 \u0443 \u043C\u0438\u043D\u0443\u0442\u0438 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0443\u0458\u0435 \u0441\u0440\u0447\u0430\u043D\u0438 \u0440\u0438\u0442\u0430\u043C, \u043A\u0440\u0432\u043D\u0438 \u043F\u0440\u0438\u0442\u0438\u0441\u0430\u043A \u0438 \u043D\u0435\u0440\u0432\u043D\u0438 \u0441\u0438\u0441\u0442\u0435\u043C \u2014 \u043F\u043E\u0441\u0442\u0438\u0436\u0443\u045B\u0438 \u0441\u0442\u0430\u045A\u0435 \u0437\u0432\u0430\u043D\u043E "\u043A\u043E\u0445\u0435\u0440\u0435\u043D\u0446\u0438\u0458\u0430" \u0437\u0430 \u043E\u043F\u0442\u0438\u043C\u0430\u043B\u0430\u043D HRV.',
  'techniques.triangle.detail': '\u041D\u0435\u0436\u0430\u043D 3-\u0444\u0430\u0437\u043D\u0438 \u043E\u0431\u0440\u0430\u0437\u0430\u0446 \u0441\u0430\u0432\u0440\u0448\u0435\u043D \u0437\u0430 \u043F\u043E\u0447\u0435\u0442\u043D\u0438\u043A\u0435. \u0423\u0440\u0430\u0432\u043D\u043E\u0442\u0435\u0436\u0443\u0458\u0435 \u043D\u0435\u0440\u0432\u043D\u0438 \u0441\u0438\u0441\u0442\u0435\u043C \u0431\u0435\u0437 \u0437\u0430\u0434\u0440\u0436\u0430\u0432\u0430\u045A\u0430 \u0434\u0430\u0445\u0430, \u0448\u0442\u043E \u0433\u0430 \u0447\u0438\u043D\u0438 \u043B\u0430\u043A\u0438\u043C \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0438\u043C \u0437\u0430 \u0441\u0432\u0435.',
  'techniques.power.detail': '\u0418\u043D\u0441\u043F\u0438\u0440\u0438\u0441\u0430\u043D\u043E \u043C\u0435\u0442\u043E\u0434\u043E\u043C \u0412\u0438\u043C \u0425\u043E\u0444. \u0411\u0440\u0437\u043E \u0434\u0438\u0441\u0430\u045A\u0435 \u043F\u0440\u0430\u045B\u0435\u043D\u043E \u0437\u0430\u0434\u0440\u0436\u0430\u0432\u0430\u045A\u0435\u043C \u0434\u0430\u0445\u0430 \u043F\u043E\u0432\u0435\u045B\u0430\u0432\u0430 \u0435\u043D\u0435\u0440\u0433\u0438\u0458\u0443, \u0430\u043B\u043A\u0430\u043B\u0438\u0437\u0443\u0458\u0435 \u043A\u0440\u0432 \u0438 \u043F\u043E\u0458\u0430\u0447\u0430\u0432\u0430 \u0438\u043C\u0443\u043D\u0438 \u043E\u0434\u0433\u043E\u0432\u043E\u0440.',
  'techniques.fourFourSixTwo.detail': '\u041F\u0440\u043E\u0434\u0443\u0436\u0435\u043D\u0438 \u0438\u0437\u0434\u0438\u0441\u0430\u0458 (6\u0441) \u0443 \u043E\u0434\u043D\u043E\u0441\u0443 \u043D\u0430 \u0443\u0434\u0438\u0441\u0430\u0458 (4\u0441) \u043F\u0440\u0435\u0431\u0430\u0446\u0443\u0458\u0435 \u0442\u0435\u043B\u043E \u0443 \u0434\u0443\u0431\u043E\u043A\u0443 \u0440\u0435\u043B\u0430\u043A\u0441\u0430\u0446\u0438\u0458\u0443. \u041A\u0440\u0430\u0442\u043A\u0430 \u043F\u0430\u0443\u0437\u0430 \u0438\u0437\u043C\u0435\u0452\u0443 \u0446\u0438\u043A\u043B\u0443\u0441\u0430 \u0440\u0435\u0441\u0435\u0442\u0443\u0458\u0435 \u0440\u0438\u0442\u0430\u043C \u0434\u0438\u0441\u0430\u045A\u0430.',
  'techniques.kapalabhati.detail': '\u0414\u0440\u0435\u0432\u043D\u0430 \u0458\u043E\u0433\u0430 \u0442\u0435\u0445\u043D\u0438\u043A\u0430 \u0448\u0442\u043E \u0437\u043D\u0430\u0447\u0438 "\u0434\u0430\u0445 \u0441\u0458\u0430\u0458\u043D\u0435 \u043B\u043E\u0431\u0430\u045A\u0435". \u0411\u0440\u0437\u0438 \u0441\u043D\u0430\u0436\u043D\u0438 \u0438\u0437\u0434\u0438\u0441\u0430\u0458\u0438 \u0435\u043D\u0435\u0440\u0433\u0438\u0437\u0438\u0440\u0430\u0458\u0443 \u0442\u0435\u043B\u043E, \u0431\u0438\u0441\u0442\u0440\u0435 \u0443\u043C \u0438 \u0458\u0430\u0447\u0430\u0458\u0443 \u0434\u0438\u0458\u0430\u0444\u0440\u0430\u0433\u043C\u0443.',
  'techniques.twoToOne.detail': '\u0418\u0437\u0434\u0438\u0441\u0430\u0458 \u0458\u0435 \u0434\u0432\u043E\u0441\u0442\u0440\u0443\u043A\u043E \u0434\u0443\u0436\u0438 \u043E\u0434 \u0443\u0434\u0438\u0441\u0430\u0458\u0430, \u043C\u0430\u043A\u0441\u0438\u043C\u0438\u0437\u0438\u0440\u0430\u0458\u0443\u045B\u0438 \u043E\u0441\u043B\u043E\u0431\u0430\u0452\u0430\u045A\u0435 CO\u2082 \u0438 \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u0430\u0458\u0443\u045B\u0438 \u0432\u0430\u0433\u0443\u0441\u043D\u0438 \u0436\u0438\u0432\u0430\u0446. \u0408\u0435\u0434\u0430\u043D \u043E\u0434 \u043D\u0430\u0458\u0435\u0444\u0438\u043A\u0430\u0441\u043D\u0438\u0458\u0438\u0445 \u043E\u0431\u0440\u0430\u0437\u0430\u0446\u0430 \u0437\u0430 \u0434\u0443\u0431\u043E\u043A\u0443 \u0440\u0435\u043B\u0430\u043A\u0441\u0430\u0446\u0438\u0458\u0443.',
  'techniques.cyclicSigh.detail': '\u0421\u0442\u0443\u0434\u0438\u0458\u0430 \u0421\u0442\u0435\u043D\u0444\u043E\u0440\u0434\u0430 \u0458\u0435 \u043F\u043E\u043A\u0430\u0437\u0430\u043B\u0430 \u0434\u0430 \u0458\u0435 5 \u043C\u0438\u043D\u0443\u0442\u0430 \u0446\u0438\u043A\u043B\u0438\u0447\u043D\u043E\u0433 \u0443\u0437\u0434\u0438\u0441\u0430\u045A\u0430 \u0435\u0444\u0438\u043A\u0430\u0441\u043D\u0438\u0458\u0435 \u0437\u0430 \u0441\u043C\u0430\u045A\u0435\u045A\u0435 \u0441\u0442\u0440\u0435\u0441\u0430 \u043E\u0434 \u043C\u0435\u0434\u0438\u0442\u0430\u0446\u0438\u0458\u0435. \u0414\u0432\u043E\u0441\u0442\u0440\u0443\u043A\u0438 \u0443\u0434\u0438\u0441\u0430\u0458 + \u043F\u0440\u043E\u0434\u0443\u0436\u0435\u043D\u0438 \u0438\u0437\u0434\u0438\u0441\u0430\u0458 \u0440\u0435\u0441\u0435\u0442\u0443\u0458\u0435 \u043D\u0435\u0440\u0432\u043D\u0438 \u0441\u0438\u0441\u0442\u0435\u043C.',

